   21	/**
   22	 * Answers whether this account can legally queue a unit right now, and which one.
   23	 *
   24	 * Roles are taken in the order a miner's opening takes them: cargo first, because every later
   25	 * fleet action needs somewhere to put loot and resources, then the colony ship that unlocks a
   26	 * second planet, which is what fleetsave, transport and scouting all wait on. The two intel-driven
   27	 * roles come after the opening, because each waits on an observation: defence when the host says a
   28	 * hostile is inbound or when the planet has something the need evaluator says is worth a wall, and
   29	 * a combat escort when a fresh report shows a defended target the account's own fleet is not
   30	 * expected to crack.
   31	 *
   32	 * Power is the one role the building queue shares: a planet that is short and whose capacity the
   33	 * building queue cannot take buys it from the yard instead, which is what a player does when the
   34	 * plant is out of reach or the queue is busy. It is offered only when the building planner's own
   35	 * gate says no, so the two never compete over the same shortfall.
   36	 *
   37	 * Which object fills each role is read from the host: cargo is the ship with the largest cargo
   38	 * capacity per metal-equivalent cost the planet can actually queue, combat is the hull with the best
   39	 * attack per metal-equivalent cost, the colony ship is the ship the host's own colonisation mission
   40	 * consumes, and defence is the component `DefenseCompositionPlanner` says this account's doctrine is
   41	 * most behind on. A mod-added hull with a better ratio becomes its role's unit with no edit here.
   42	 */
   43	class QueueableUnitPlanner
   44	{
   45	    private const CRYSTAL_WEIGHT = 1.5;
   46	
   47	    private const DEUTERIUM_WEIGHT = 2.0;
   48	
   49	    /** The first cargo batch is one hull: sizing for a raid payload arrives with the raid itself. */
   50	    private const FIRST_CARGO_AMOUNT = 1;
   51	
   52	    /** The same 24 h staleness window the observation publishes target reports with. */
   53	    private const INTEL_TTL_HOURS = 24;
   54	
   55	    public function __construct(
   56	        private PlayerServiceFactory $playerServiceFactory,
   57	        private EnergyCapacity $energyCapacity,
   58	        private QueueableBuildingPlanner $buildingPlanner,
   59	        private DefenseCompositionPlanner $defenseComposition,
   60	        private DefenseNeedEvaluator $defenseNeed,
   61	    ) {}
   62	
   63	    public function plan(int $playerId, ?PlayerService $player = null): ?QueueableUnit
   64	    {
   65	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
   66	        if ($profile === null) {
   67	            return null;
   68	        }
   69	
   70	        if (! User::query()->whereKey($playerId)->exists()) {
   71	            return null;
   72	        }
   73	
   74	        $player ??= $this->playerServiceFactory->make($playerId, true);
   75	        $planets = $player->planets->all();
   76	        if ($planets === []) {
   77	            return null;
   78	        }
   79	
   80	        $underAttack = $this->underAttack($player);
   81	
   82	        // Standing defence is collected across the account and chosen once at the end. Returning on
   83	        // the first planet that wanted anything let the planet with the most to lose take every order:
   84	        // need grows with production, so the homeworld's need was never satisfied and its colonies were
   85	        // never reached -- 125 of 158 grand-test planets sat at zero defence while one held 40,643.
   86	        $standing = [];
   87	
   88	        // Power outranks the habits below but not an incoming attack. A planet that is throttling
   89	        // loses production every hour it stays short, wherever it sits on the account, so it is
   90	        // answered before a habit on another planet gets its turn -- the same reason the building
   91	        // planner runs its storage pass before its routine. The building planner has already
   92	        // refreshed every planet's balance earlier in this perception, so the shortfall read here
   93	        // is the session's own.
   94	        if (! $underAttack) {
   95	            foreach ($planets as $planet) {
   96	                $power = $this->powerFromYard($planet);
   97	                if ($power !== null) {
   98	                    return $power;
   99	                }
  100	            }
  101	        }
  102	
  103	        foreach ($planets as $planet) {
  104	            $planet->updateResources(false);
  105	
  106	            // Whether this planet wants a wall, and how big. Asked before the wall is composed so
  107	            // the same answer sizes both the reactive and the standing defence below.
  108	            $need = $this->defenseNeed->evaluate($player, $planet);
  109	
  110	            // Cargo first, and only while the account owns no ship at all: a fleet begins with
  111	            // one hull that can carry, and nothing else is worth building before that exists.
  112	            if ($this->ownsNoShip($planet)) {
  113	                $cargo = $this->bestCargo($player, $planet);
  114	                if ($cargo !== null) {
  115	                    return $this->unit($planet, $cargo, 'role:cargo:'.$cargo->machine_name);
  116	                }
  117	
  118	                continue;
  119	            }
  120	
  121	            // Defence is reactive and time-sensitive: an inbound hostile makes it worth buying
  122	            // before anything else on this planet, and the host's own "under attack" is the
  123	            // trigger, so the module keeps no mission-type list.
  124	            if ($underAttack) {
  125	                $defense = $this->defenseComposition->plan($player, $planet, $need);
  126	                if ($defense !== null) {
  127	                    return $this->unit($planet, $defense->unit, 'role:defense:'.$defense->unit->machine_name, $defense->amount);
  128	                }
  129	            }
  130	
  131	            // Expansion: a colony ship once a fleet exists, the account has room, and none is
  132	            // already owned. One colony ship is the second planet every later fleet move needs.
  133	            if (! $this->ownsColonyShip($planet) && $player->planets->planetCount() < $player->getMaxPlanetAmount()) {
  134	                $colonyShip = ObjectService::getUnitObjectByMachineName(ColonisationMission::getRequiredShipMachineNames()[0]);
  135	                if ($this->queueable($planet, $colonyShip)) {
  136	                    return $this->unit($planet, $colonyShip, 'role:colony');
  137	                }
  138	            }
  139	
  140	            // Scouting: a probe once a fleet exists, so the account can start seeing neighbours.
  141	            if (! $this->ownsProbe($planet)) {
  142	                $probe = ObjectService::getUnitObjectByMachineName(EspionageMission::getRequiredShipMachineNames()[0]);
  143	                if ($this->queueable($planet, $probe)) {
  144	                    return $this->unit($planet, $probe, 'role:probe');
  145	                }
  146	            }
  147	
  148	            // Escort: a fresh report on a defended target and no warship of our own means the
  149	            // account wants the cheapest combat hull, so a later raid has something to attack
  150	            // with. The hull is the best attack-per-cost the planet can queue, never a named ship.
  151	            if ($this->observedDefendedTarget($playerId)) {
  152	                $escort = $this->bestEscort($player, $planet);
  153	                if ($escort !== null && $this->needsEscort($player, $planet, $escort)) {
  154	                    return $this->unit($planet, $escort, 'role:escort:'.$escort->machine_name);
  155	                }
  156	            }
  157	
  158	            // Cargo sizing: once the opening fleet exists, grow the cargo to the
  159	            // raid payload the freshest report promises, not a fixed one (FLE-010).
  160	            $cargoPlan = $this->cargoForPayload($player, $planet, $playerId);
  161	            if ($cargoPlan !== null) {
  162	                return $cargoPlan;
  163	            }
  164	
  165	            // Standing defence: what the planet stands to lose decides whether it wants a wall and
  166	            // how big, so it is never naked between attacks -- not only when the host already says
  167	            // a hostile is inbound. A planet whose wall already covers its exposure wants nothing.
  168	            // Candidates are collected rather than returned: the choice between them is made below,
  169	            // where the whole account is visible.
  170	            if ($need === null) {
  171	                continue;
  172	            }
  173	
  174	            $defense = $this->defenseComposition->plan($player, $planet, $need);
  175	            if ($defense !== null && !$this->starvesSaving($planet, $profile, $defense)) {
  176	                $standing[] = [$planet, $defense];
  177	            }
  178	        }
  179	
  180	        if ($standing !== []) {
  181	            // The least-defended planet that still wants a wall takes the next order, so a wall rises
  182	            // everywhere it is wanted instead of forever in one place. Counting units rather than
  183	            // pricing them keeps this one comparison and no second valuation.
  184	            usort($standing, static fn (array $a, array $b): int => $a[0]->getDefenseUnits()->getAmount() <=> $b[0]->getDefenseUnits()->getAmount());
  185	            [$planet, $defense] = $standing[0];
  186	
  187	            return $this->unit($planet, $defense->unit, 'role:defense:standing:'.$defense->unit->machine_name, $defense->amount);
  188	        }
  189	
  190	        return null;
  191	    }
  192	
  193	    private function unit(PlanetService $planet, UnitObject $ship, string $reason, int $amount = self::FIRST_CARGO_AMOUNT): QueueableUnit
  194	    {
  195	        return app()->makeWith(QueueableUnit::class, [
