20	/**
21	 * Module-owned adapter over the host's colonisation fleet path.
22	 *
23	 * The decision is the module's; the mission, its legality and the slot check are
24	 * the host's. The colony ship is deducted atomically by the host's own mission
25	 * start, so this adapter only refuses what the host would refuse anyway and
26	 * reports whether a mission row actually appeared.
27	 */
28	class QueueAiColonyAction implements QueueAiColony
29	{
30	    public function __construct(
31	        private PlayerGameStateService $playerGameStateService,
32	        private PlanetServiceFactory $planetServiceFactory,
33	    ) {
34	    }
35	
36	    public function handle(int $playerId, int $planetId, int $galaxy, int $system, int $position): AiActionResult
37	    {
38	        if (!Planet::query()->whereKey($planetId)->where('user_id', $playerId)->exists()) {
39	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
40	        }
41	
42	        try {
43	            $player = $this->playerGameStateService->advance($playerId, $planetId);
44	
45	            if ($player->isBanned()) {
46	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
47	            }
48	            if ($player->isInVacationMode()) {
49	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
50	            }
51	
52	            $planet = $this->planetServiceFactory->makeForPlayer($player, $planetId, false);
53	            $units = new UnitCollection();
54	            // The ship the host's own colonisation mission consumes; the name comes from the
55	            // mission, never from a module constant.
56	            $colonyShip = ObjectService::getUnitObjectByMachineName(ColonisationMission::getRequiredShipMachineNames()[0]);
57	            $units->addUnit($colonyShip, 1);
58	
59	            $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
60	            $mission = $fleetMissions->createNewFromPlanet(
61	                $planet,
62	                new Coordinate($galaxy, $system, $position),
63	                PlanetType::Planet,
64	                ColonisationMission::getTypeId(),
65	                $units,
66	                new Resources(),
67	                10,
68	            );
69	
70	            return AiActionResult::queued($mission->id);
71	        } catch (Exception $exception) {
72	            return AiActionResult::rejected($exception->getMessage());
73	        }
